function QRCode(el, options) {
  const texto = typeof options === "string" ? options : options.text;
  const tamanho = options.width || 300;
  const corFrente = (options.colorDark || "#000000").replace("#", "");
  const corFundo = (options.colorLight || "#ffffff").replace("#", "");

  const canvas = document.createElement("canvas");
  canvas.width = tamanho;
  canvas.height = tamanho;
  el.innerHTML = "";
  el.appendChild(canvas);

  const ctx = canvas.getContext("2d");

  // Lista de servidores confiáveis de fallback caso um esteja lento na rede móvel
    const servidores = [
    "https://qrserver.com" + tamanho + "x" + tamanho + "&data=" + encodeURIComponent(texto) + "&color=" + corFrente + "&bgcolor=" + corFundo + "&ecc=H&margin=2",
    "https://quickchart.io" + encodeURIComponent(texto) + "&size=" + tamanho + "&dark=" + corFrente + "&light=" + corFundo + "&ecLevel=H&margin=2"
  ];

  function tentarCarregar(indice) {
    if (indice >= servidores.length) {
      alert("Não foi possível gerar o QR Code. Verifique se há bloqueador de anúncios ativo no navegador.");
      return;
    }

    const img = new Image();
    img.crossOrigin = "Anonymous";
    img.onload = function () {
      ctx.drawImage(img, 0, 0, tamanho, tamanho);
    };
    img.onerror = function () {
      tentarCarregar(indice + 1);
    };
    img.src = servidores[indice];
  }

  tentarCarregar(0);
}

QRCode.CorrectLevel = { L: 1, M: 0, Q: 3, H: 2 };
